/*
 * Ticketed console sessions for remote (CloudAPI) console access.
 *
 * A ticket is issued through "vmadm info <uuid> console". It names a TCP
 * host:port and a single-use token that expires after ticketTtl ms. The
 * listener only exists while tickets or unauthenticated connections are
 * outstanding.
 *
 * Wire protocol on the TCP connection:
 *
 *   client -> broker   <64 hex char token>\n
 *   broker -> client   OK\n                  then raw console bytes
 *                      ERR <reason>\n        then close
 *
 * Only one session per VM is allowed. zoneadmd also only serves one console
 * client, so a zone console held by zlogin -C fails with "ERR busy".
 */

var assert = require('/usr/node/node_modules/assert-plus');
var crypto = require('crypto');
var net = require('net');
var path = require('path');

var TOKEN_RE = /^[0-9a-f]{64}$/;
var MAX_LINE = 256;

var DEFAULTS = {
    ticketTtl: 30 * 1000,
    authTimeout: 5 * 1000,
    backendTimeout: 5 * 1000,
    idleTimeout: 30 * 60 * 1000,
    maxPending: 16,
    maxTicketsPerVm: 4,
    zoneSockDir: '/var/run/zones'
};

function hashToken(token)
{
    return (crypto.createHash('sha256').update(token).digest('hex'));
}

/*
 * Returns {path, type, handshake} for the VM's console, or throws if the VM
 * cannot have a remote console.
 */
function consoleTarget(vmobj, zoneSockDir)
{
    var zonepath = vmobj.zonepath || path.join('/zones', vmobj.uuid);

    if (vmobj.docker) {
        throw (new Error('console access is not supported for docker VMs'));
    }

    switch (vmobj.brand) {
    case 'kvm':
        return ({
            path: path.join(zonepath, 'root/tmp/vm.console'),
            type: 'serial',
            handshake: false
        });
    case 'bhyve':
    case 'joyent':
    case 'joyent-minimal':
    case 'lx':
        return ({
            path: path.join(zoneSockDir || DEFAULTS.zoneSockDir,
                vmobj.zonename + '.console_sock'),
            type: (vmobj.brand === 'bhyve') ? 'serial' : 'zone',
            handshake: true
        });
    default:
        throw (new Error('console access is not supported for brand "'
            + vmobj.brand + '"'));
    }
}

/*
 * Reads one '\n' terminated line from sock. Calls cb(err, line, rest) where
 * rest is any data received after the newline. Uses read() rather than 'data'
 * so the socket stays in paused mode and can be piped afterwards on node 0.10.
 */
function readLine(sock, cb)
{
    var bufs = [];
    var finished = false;
    var len = 0;

    function onReadable() {
        var buf;
        var chunk;
        var idx;

        while (!finished && (chunk = sock.read()) !== null) {
            bufs.push(chunk);
            len += chunk.length;
            buf = Buffer.concat(bufs, len);
            idx = -1;
            for (var i = 0; i < buf.length; i++) {
                if (buf[i] === 0x0a) {
                    idx = i;
                    break;
                }
            }

            if (idx !== -1) {
                finish(null, buf.slice(0, idx).toString('ascii')
                    .replace(/\r$/, ''), buf.slice(idx + 1));
            } else if (len > MAX_LINE) {
                finish(new Error('line too long'));
            }
        }
    }

    function onEnd() {
        finish(new Error('connection closed'));
    }

    function finish(err, line, rest) {
        if (finished) {
            return;
        }
        finished = true;
        sock.removeListener('readable', onReadable);
        sock.removeListener('end', onEnd);
        cb(err, line, rest);
    }

    sock.on('readable', onReadable);
    sock.on('end', onEnd);
}

function ConsoleBroker(opts)
{
    var k;

    assert.object(opts, 'opts');
    assert.object(opts.log, 'opts.log');
    assert.string(opts.host, 'opts.host');

    this.log = opts.log;
    this.host = opts.host;
    for (k in DEFAULTS) {
        if (DEFAULTS.hasOwnProperty(k)) {
            this[k] = opts.hasOwnProperty(k) ? opts[k] : DEFAULTS[k];
        }
    }

    this.tickets = {};      // token hash -> ticket
    this.sessions = {};     // vm uuid -> session
    this.pending = 0;       // connections that have not authenticated yet
    this.server = null;
    this.port = null;
    this.listenWaiters = null;
}

/*
 * Issues a ticket for vmobj, which needs brand, docker, uuid, zonename and
 * zonepath. Calls cb(err, {host, port, token, type, expires_in}).
 */
ConsoleBroker.prototype.issue = function issue(vmobj, cb)
{
    var self = this;
    var target;
    var ticket;
    var token;

    assert.object(vmobj, 'vmobj');
    assert.uuid(vmobj.uuid, 'vmobj.uuid');
    assert.func(cb, 'cb');

    try {
        target = consoleTarget(vmobj, self.zoneSockDir);
    } catch (err) {
        cb(err);
        return;
    }

    self._limitTickets(vmobj.uuid);

    token = crypto.randomBytes(32).toString('hex');
    ticket = {
        hash: hashToken(token),
        uuid: vmobj.uuid,
        path: target.path,
        type: target.type,
        handshake: target.handshake,
        issued: Date.now(),
        timer: null
    };
    ticket.timer = setTimeout(function expireTicket() {
        self.log.info({vm: ticket.uuid}, 'console ticket expired unused');
        self._dropTicket(ticket);
    }, self.ticketTtl);
    self.tickets[ticket.hash] = ticket;

    self._ensureListening(function onListening(err) {
        if (err) {
            self._dropTicket(ticket);
            cb(err);
            return;
        }

        self.log.info({vm: ticket.uuid, port: self.port, type: ticket.type},
            'issued console ticket');
        cb(null, {
            host: self.host,
            port: self.port,
            token: token,
            type: ticket.type,
            expires_in: Math.floor(self.ticketTtl / 1000)
        });
    });
};

/*
 * Drops any unused tickets for a VM and ends its active session.
 */
ConsoleBroker.prototype.revoke = function revoke(uuid)
{
    var self = this;

    Object.keys(self.tickets).forEach(function (h) {
        if (self.tickets[h].uuid === uuid) {
            self._dropTicket(self.tickets[h]);
        }
    });

    if (self.sessions.hasOwnProperty(uuid)) {
        self.sessions[uuid].teardown('VM stopped');
    }
};

ConsoleBroker.prototype.close = function close()
{
    var self = this;

    Object.keys(self.sessions).forEach(function (uuid) {
        self.sessions[uuid].teardown('broker closed');
    });
    Object.keys(self.tickets).forEach(function (h) {
        self._dropTicket(self.tickets[h]);
    });
    self._stopListening();
};

ConsoleBroker.prototype._limitTickets = function _limitTickets(uuid)
{
    var self = this;
    var mine;

    mine = Object.keys(self.tickets).map(function (h) {
        return (self.tickets[h]);
    }).filter(function (t) {
        return (t.uuid === uuid);
    }).sort(function (a, b) {
        return (a.issued - b.issued);
    });

    while (mine.length >= self.maxTicketsPerVm) {
        self._dropTicket(mine.shift());
    }
};

ConsoleBroker.prototype._dropTicket = function _dropTicket(ticket)
{
    clearTimeout(ticket.timer);
    if (this.tickets[ticket.hash] === ticket) {
        delete this.tickets[ticket.hash];
    }
    this._maybeStopListening();
};

ConsoleBroker.prototype._takeTicket = function _takeTicket(token)
{
    var hash;
    var ticket;

    if (!TOKEN_RE.test(token)) {
        return (null);
    }

    hash = hashToken(token);
    if (!this.tickets.hasOwnProperty(hash)) {
        return (null);
    }

    ticket = this.tickets[hash];
    clearTimeout(ticket.timer);
    delete this.tickets[hash];
    return (ticket);
};

ConsoleBroker.prototype._ensureListening = function _ensureListening(cb)
{
    var self = this;
    var server;

    if (self.server !== null && self.listenWaiters === null) {
        cb(null);
        return;
    }
    if (self.listenWaiters !== null) {
        self.listenWaiters.push(cb);
        return;
    }

    self.listenWaiters = [cb];
    server = net.createServer(function onConn(c) {
        self._handleConnection(c);
    });
    self.server = server;

    function done(err) {
        var waiters = self.listenWaiters;

        self.listenWaiters = null;
        waiters.forEach(function (w) {
            w(err);
        });
    }

    server.once('error', function onListenError(err) {
        self.log.error({err: err}, 'console listener failed to start');
        if (self.server === server) {
            self.server = null;
            self.port = null;
        }
        done(err);
    });

    server.listen(0, self.host, function onListen() {
        server.removeAllListeners('error');
        server.on('error', function onServerError(err) {
            self.log.error({err: err}, 'console listener error');
        });
        self.port = server.address().port;
        self.log.info({host: self.host, port: self.port},
            'console listener started');
        done(null);
        self._maybeStopListening();
    });
};

ConsoleBroker.prototype._maybeStopListening = function _maybeStopListening()
{
    if (this.server === null || this.listenWaiters !== null) {
        return;
    }
    if (Object.keys(this.tickets).length > 0 || this.pending > 0) {
        return;
    }
    this._stopListening();
};

ConsoleBroker.prototype._stopListening = function _stopListening()
{
    if (this.server === null) {
        return;
    }
    this.log.info({port: this.port}, 'console listener stopped');
    try {
        this.server.close();
    } catch (_) {
        // close() throws if the server never finished listening.
    }
    this.server = null;
    this.port = null;
};

ConsoleBroker.prototype._handleConnection = function _handleConnection(c)
{
    var self = this;
    var authed = false;
    var remote = '[' + c.remoteAddress + ']:' + c.remotePort;
    var timer;

    if (self.pending >= self.maxPending) {
        self.log.warn({remote: remote},
            'too many unauthenticated console connections');
        c.destroy();
        return;
    }
    self.pending++;

    function unpend() {
        if (!authed) {
            authed = true;
            self.pending--;
            clearTimeout(timer);
            self._maybeStopListening();
        }
    }

    c.on('error', function onPreAuthError(err) {
        self.log.debug({err: err, remote: remote},
            'console connection error before auth');
    });
    c.on('close', unpend);

    timer = setTimeout(function authTimeout() {
        self.log.warn({remote: remote}, 'console auth timed out');
        c.destroy();
    }, self.authTimeout);

    readLine(c, function onTokenLine(err, line, rest) {
        var ticket;

        if (err) {
            unpend();
            c.destroy();
            return;
        }

        ticket = self._takeTicket(line);
        unpend();
        c.removeListener('close', unpend);

        if (ticket === null) {
            self.log.warn({remote: remote}, 'console auth failed');
            c.end('ERR invalid token\n');
            return;
        }

        self._startSession(c, ticket, rest, remote);
    });
};

ConsoleBroker.prototype._startSession =
function _startSession(c, ticket, clientRest, remote)
{
    var self = this;
    var backend;
    var done = false;
    var session;
    var timer;

    if (self.sessions.hasOwnProperty(ticket.uuid)) {
        self.log.warn({vm: ticket.uuid, remote: remote},
            'console already in use by another session');
        c.end('ERR busy\n');
        return;
    }

    session = {
        teardown: teardown
    };
    self.sessions[ticket.uuid] = session;

    function teardown(why) {
        if (done) {
            return;
        }
        done = true;
        clearTimeout(timer);
        if (self.sessions[ticket.uuid] === session) {
            delete self.sessions[ticket.uuid];
        }
        self.log.info({vm: ticket.uuid, remote: remote, reason: why},
            'console session ended');
        if (backend) {
            backend.destroy();
        }
        c.destroy();
    }

    function fail(reason, err) {
        if (done) {
            return;
        }
        self.log.warn({vm: ticket.uuid, remote: remote, err: err},
            'console session failed: ' + reason);
        done = true;
        clearTimeout(timer);
        if (self.sessions[ticket.uuid] === session) {
            delete self.sessions[ticket.uuid];
        }
        if (backend) {
            backend.destroy();
        }
        c.end('ERR ' + reason + '\n');
    }

    function ready(backendRest) {
        clearTimeout(timer);
        self.log.info({vm: ticket.uuid, remote: remote, type: ticket.type},
            'console session started');

        backend.removeAllListeners('error');
        c.removeAllListeners('error');
        backend.on('error', function (err) {
            teardown('backend error: ' + err.message);
        });
        c.on('error', function (err) {
            teardown('client error: ' + err.message);
        });
        backend.on('close', function () {
            teardown('backend closed');
        });
        c.on('close', function () {
            teardown('client closed');
        });

        c.setNoDelay(true);
        c.setTimeout(self.idleTimeout, function () {
            teardown('idle timeout');
        });

        c.write('OK\n');
        if (backendRest && backendRest.length > 0) {
            c.write(backendRest);
        }
        if (clientRest && clientRest.length > 0) {
            backend.write(clientRest);
        }
        backend.pipe(c);
        c.pipe(backend);
    }

    function onEarlyClose() {
        fail('client closed');
    }
    c.on('close', onEarlyClose);

    timer = setTimeout(function backendTimeout() {
        fail('console not responding');
    }, self.backendTimeout);

    backend = net.connect(ticket.path);
    backend.on('error', function onBackendError(err) {
        fail('console unavailable', err);
    });
    backend.once('connect', function onBackendConnect() {
        if (!ticket.handshake) {
            c.removeListener('close', onEarlyClose);
            ready(null);
            return;
        }

        // Same identification zlogin -C sends: locale C, no disconnect flag.
        backend.write('IDENT C 0\n');
        readLine(backend, function onIdentReply(err, line, rest) {
            if (done) {
                return;
            }
            if (err) {
                fail('console handshake failed', err);
                return;
            }
            if (line === 'OK') {
                c.removeListener('close', onEarlyClose);
                ready(rest);
                return;
            }
            // zoneadmd replies with the pid of the current client.
            if (/^[0-9]+$/.test(line)) {
                fail('busy');
                return;
            }
            fail('console handshake failed');
        });
    });
};

module.exports = {
    ConsoleBroker: ConsoleBroker,
    consoleTarget: consoleTarget
};
